'use strict';

// Verified location photos and clearly labelled concept illustrations stay distinct.
function stationIllustration(s){return window.ECOCHARGE_STATION_VISUALS?.illustrations[s.id]||{kind:'illustration',path:'assets/station-illustration.svg',alt:'Concept illustration, not a photograph of '+s.city+' station',location:s.city+', '+s.state,source:s.source,credit:'EcoCharge · concept illustration'};}
function stationPhoto(s){return demo.stationPhotos?.[s.id]||photoCatalog[s.id]||stationIllustration(s)}
function missingPhoto(s){const p=stationIllustration(s);return `<div class="station-fallback-image"><img src="${escapeHtml(p.path)}" alt="${escapeHtml(p.alt)}" width="900" height="600"><span>Concept illustration · Photo unavailable</span></div>`}
updateStationPhoto=function(s){const area=$('.station-photo');const photo=stationPhoto(s);area.classList.toggle('no-photo',!photo);$('.station-status>span').innerHTML=photo?.operationalNote?'Operator update: upgrade closure':'<i class="status-dot"></i>Listed available in AFDC';area.innerHTML=photo?`<img src="${escapeHtml(photo.path)}" alt="${escapeHtml(photo.alt)}" data-station-photo="${s.id}" width="1280" height="960" style="object-position:${escapeHtml(photo.position||'center')}"><span class="photo-location">${escapeHtml(s.city)}, ${s.state}${photo.kind==='illustration'?' · Illustration':photo.dateTaken?' · '+photo.dateTaken.slice(0,4):' · Location photo'}</span><a class="photo-credit" href="${escapeHtml(photo.source)}" target="_blank" rel="noopener">${escapeHtml(photo.credit)}</a>`:missingPhoto(s)};
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||!img.dataset.stationPhoto)return;const s=stations.find(s=>s.id===Number(img.dataset.stationPhoto));if(!s)return;const area=img.closest('.station-photo,.station-dialog-photo');if(area){area.classList.add('no-photo');area.innerHTML=missingPhoto(s)}},true);
actions.station=function(){if(!selected)return;const s=selected,photo=stationPhoto(s),allocated=demo.plan?.stationIds.includes(s.id)?demo.plan.capital/demo.plan.stationIds.length:null;openModal(`<div class="station-dialog-eyebrow">STATION RECORD · AFDC ${s.id}</div><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.address)}, ${escapeHtml(s.city)}, ${s.state} ${s.zip}</p><figure class="station-dialog-photo">${photo?`<img src="${escapeHtml(photo.path)}" alt="${escapeHtml(photo.alt)}" data-station-photo="${s.id}"><figcaption>${photo.kind==='illustration'?'Concept illustration · not a location photo':'Photo of this location'} · <a href="${escapeHtml(photo.source)}" target="_blank" rel="noopener">${escapeHtml(photo.credit)}</a>${photo.dateTaken?' · '+photo.dateTaken:''}${photo.licenseUrl?' · <a href="'+escapeHtml(photo.licenseUrl)+'" target="_blank" rel="noopener">License ↗</a>':''}<span class="photo-crop-note"> ${photo.kind==='illustration'?'Actual station appearance is not shown.':'Displayed crop · Photo date does not indicate current availability.'}</span></figcaption>`:missingPhoto(s)}</figure><div class="station-detail-grid"><div><small>Network</small><strong>Electrify America</strong></div><div><small>DC fast ports</small><strong>${s.ports}</strong></div><div><small>Maximum listed power</small><strong>${s.maxKw?s.maxKw+' kW':'Not listed'}</strong></div><div><small>Directory confirmed</small><strong>${s.confirmed}</strong></div></div>${photo?.operationalNote?'<p class="modal-note">'+escapeHtml(photo.operationalNote)+' <a href="'+escapeHtml(photo.operationalSource)+'" target="_blank" rel="noopener">Operator update ↗</a></p>':''}<div class="station-invest-box"><div><span>${allocated?'Your demo allocation':'Starting demo rate'}</span><strong>${allocated?money(allocated):demo.tariffs[0].rate+'%'} <small>${allocated?'allocated to this station':'per week on total allocated capital'}</small></strong></div><button class="button primary" data-action="invest-selected">${allocated?'Manage investment selection':'Select for investment'} ${icon('arrow')}</button><small>Demo only. This public listing does not establish company ownership or investment availability.</small></div><div class="station-dialog-links"><a href="https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lng}" target="_blank" rel="noopener">View on Google Maps ↗</a><a href="${s.source}" target="_blank" rel="noopener">AFDC record ↗</a><button data-action="factsheet">Download fact sheet</button>${role==='admin'?`<button data-edit-photo="${s.id}">Manage location photo</button>`:''}</div>`)};

function showPhotoEditor(id){const s=stations.find(s=>s.id===Number(id));if(!s)return;const p=demo.stationPhotos?.[id];openModal(`<h2>Station photo</h2><p><strong>${escapeHtml(s.name)}</strong><br>${escapeHtml(s.address)}, ${escapeHtml(s.city)}, ${s.state}<br>AFDC ${s.id}</p><form id="station-photo-form" data-station-id="${s.id}"><label for="photo-url">Photo URL · HTTPS</label><input id="photo-url" type="url" value="${escapeHtml(p?.path||'')}" placeholder="https://example.com/station.jpg" required><label for="photo-source">Source page · HTTPS</label><input id="photo-source" type="url" value="${escapeHtml(p?.source||'')}" placeholder="https://example.com/location" required><label for="photo-credit">Photographer / license</label><input id="photo-credit" maxlength="160" value="${escapeHtml(p?.credit||'')}" placeholder="Photo credit and permission to use" required><label class="photo-confirm"><input type="checkbox" required><span>I verified this photo shows this exact location and can be used here.</span></label><div class="form-error" id="photo-error" role="alert"></div><button class="button primary" type="submit">Save location photo</button>${p?`<button class="button secondary" type="button" data-remove-photo="${s.id}">Remove custom photo</button>`:''}</form><p class="photo-form-note">Changes apply to this station in this browser. Stations without a verified photo show a clearly labelled illustration.</p>`)}

function managerClientRecord(){const c=demo.client,p=demo.plan;return `<section class="panel client-record"><div class="client-record-top"><span class="avatar">${escapeHtml(c.name.split(/\s+/).slice(0,2).map(s=>s[0]).join(''))}</span><div class="client-record-name"><h2>${escapeHtml(c.name)}</h2><span>CL-1001 · ${escapeHtml(c.email)}</span></div><span class="pill ${c.status==='Review'?'pending':''}">${escapeHtml(c.status)}</span></div><dl class="client-record-summary"><div><dt>Demo balance</dt><dd>${money(demo.balance)}<small>${money(pendingWithdrawals())} reserved</small></dd></div><div><dt>Selected plan</dt><dd>${p?escapeHtml(p.name):'No plan'}<small>${p?p.rate+'% per week':'Awaiting selection'}</small></dd></div><div><dt>Assigned stations</dt><dd>${demo.portfolio.length}<small>Reference locations</small></dd></div></dl><div class="client-record-actions"><button class="button primary" data-action="view-client">Open client portal ${icon('out')}</button><button class="button secondary" data-action="edit-client">Edit profile</button><button class="button secondary" data-manager-view="plan">Manage plan</button><button class="button secondary" data-action="preview-contract">Documents</button></div>${c.note?`<div class="manager-note"><b>Internal note</b>${escapeHtml(c.note)}</div>`:''}</section>`}
function managerIdentity(){const m=demo.manager;return `<section class="panel manager-account"><h2>Assigned manager</h2><div class="manager-account-identity"><span class="avatar">${escapeHtml(m.name.split(/\s+/).slice(0,2).map(s=>s[0]).join(''))}</span><div><strong>${escapeHtml(m.name)}</strong><small>Client communications</small></div></div><p>${[m.whatsapp&&'WhatsApp',m.email&&'Email',m.telegram&&'Telegram'].filter(Boolean).join(' · ')||'Add contact details to enable WhatsApp, email and Telegram in the client portal.'}</p><button class="button secondary" data-action="manager-settings">Edit manager contacts</button></section>`}
function managerPlanSummary(){const p=demo.plan;return `<section class="panel admin-section"><h2>${icon('zap')} Investment plan</h2><div class="manager-plan"><div><strong>${p?escapeHtml(p.name)+' · '+money(p.capital):'No plan selected'}</strong><small>${p?p.stationIds.length+' stations · '+p.rate+'% per week (demo)':'Select a plan and assign stations for this client.'}</small></div><button class="button secondary" data-manager-view="plan">${p?'Edit plan':'Set up plan'}</button></div></section>`}
function managerPlanEditor(){const p=demo.plan,tier=demo.tariffs.find(t=>t.id===(p?.tierId||chosenTier))||demo.tariffs[0];chosenTier=tier.id;investmentDraft=p?.capital||investmentDraft||1000;chosenStations=p?.stationIds.slice()||demo.portfolio.slice();normalizeSelection(tier);return `<section class="panel manager-plan-editor"><div class="section-heading"><h2>Client investment plan</h2><span>CL-1001 · ${escapeHtml(demo.client.name)}</span></div><p class="muted">Select a weekly demo rate and allocation. Changes are shown in the client portal.</p><div class="manager-plan-fields"><div><label for="manager-tier">Plan</label><select id="manager-tier">${demo.tariffs.map(t=>`<option value="${t.id}" ${t.id===tier.id?'selected':''}>${t.name} · ${t.count} ${t.count===1?'station':'stations'} · ${t.rate}% / week</option>`).join('')}</select></div><div><label for="investment-amount">Total demo investment (USD)</label><input id="investment-amount" type="number" min="250" max="10000000" step=".01" value="${investmentDraft}"></div></div><div class="allocation-math"><div><span>Allocated to each station</span><strong id="allocation-each">—</strong></div><div class="allocation-total"><span>Weekly demo accrual</span><strong id="allocation-payout">—</strong></div></div><div class="section-heading"><h2>Selected stations</h2><span id="selection-count">${chosenStations.length} / ${tier.count} selected</span></div><input id="picker-search" class="admin-search" placeholder="Search city, state or station ID…" aria-label="Find station for demo plan"><div id="picker-results">${pickerRows(tier)}</div><div class="form-error" id="tariff-error" role="alert"></div><button class="button primary" data-action="apply-plan">Review & apply demo plan ${icon('arrow')}</button><p class="tariff-disclosure">Simulated rates. No funds move and no real return is promised.</p></section>`}
function managerClientTable(){return `<section class="panel admin-section"><div class="section-heading"><h2>Managed clients</h2><span>1 interactive demo account</span></div><div class="table-scroll"><table><thead><tr><th>Client</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><strong>${escapeHtml(demo.client.name)}</strong><small>${escapeHtml(demo.client.email)} · CL-1001</small></td><td><span class="pill">${escapeHtml(demo.client.status)}</span></td><td><button class="table-button" data-action="edit-client">Edit profile</button></td></tr></tbody></table></div></section>`}
renderAdmin=function(){ensureClient();ensureManager();ensureTariffs();const pending=demo.requests.filter(r=>r.status==='Pending').length,open=demo.tickets.filter(t=>t.status==='Open').length;const titles={overview:['Manager workspace','A clear view of the client, open requests and next actions.'],clients:['Client management','Profile, plan, documents and assigned charging stations.'],requests:['Requests & messages','Review transaction requests and reply to the client.'],stations:['Station directory','Find real locations, assign reference stations and manage photos.'],tariffs:['Plans & weekly rates','Configure the four demo plans and review accrual history.'],plan:['Manage client plan','Choose the plan, investment amount and reference stations.']};const [title,description]=titles[adminTab]||titles.overview;let content='';if(adminTab==='overview')content=managerClientRecord()+requestTable()+supportTable();if(adminTab==='clients')content=managerClientTable()+managerClientRecord()+managerPlanSummary();if(adminTab==='requests')content=requestTable()+supportTable();if(adminTab==='stations')content=stationDirectory();if(adminTab==='tariffs')content=tariffAdmin();if(adminTab==='plan')content=managerPlanEditor();$('#admin-view').innerHTML=`<header class="manager-heading"><div><span class="eyebrow">ALT-INFRA / CLIENT OPERATIONS</span><h1>${title}</h1><p>${description}</p></div><button class="button secondary" data-action="view-client">View client portal ${icon('out')}</button></header><section class="manager-kpis" aria-label="Manager overview"><button class="panel manager-kpi" data-manager-view="requests"><span>Pending requests</span>${icon('assets')}<strong>${pending}</strong><small>${pending?'Ready for review':'No requests awaiting review'}</small></button><button class="panel manager-kpi" data-manager-view="requests" data-focus-inbox="true"><span>Open messages</span>${icon('chat')}<strong>${open}</strong><small>${open?'Client needs a response':'Inbox is up to date'}</small></button><button class="panel manager-kpi" data-manager-view="stations"><span>Assigned stations</span>${icon('zap')}<strong>${demo.portfolio.length}</strong><small>Manage client selections</small></button><button class="panel manager-kpi" data-action="history"><span>Available demo balance</span>${icon('assets')}<strong>${money(demo.balance-pendingWithdrawals())}</strong><small>After pending withdrawals</small></button></section><div class="manager-layout"><div>${content}</div><aside>${managerIdentity()}${['clients','stations','plan'].includes(adminTab)?assignmentPanel():managerPlanSummary()}${activityPanel()}</aside></div>`;$('#notification-count').textContent=String(pending+open);renderNav();if(adminTab==='plan')updateTariffMath();const walker=document.createTreeWalker($('#admin-view'),NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))if(node.nodeValue.includes('John Doe')&&!node.parentElement.closest('.activity-row'))node.nodeValue=node.nodeValue.replaceAll('John Doe',demo.client.name);refreshClientProfile()};
directoryRows=function(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Station / location</th><th>Ports</th><th>Manage</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${escapeHtml(s.city)}, ${s.state}</strong><small>${escapeHtml(s.name)} · AFDC ${s.id}</small><small>${escapeHtml(s.address)} <span class="photo-status">${stationPhoto(s).kind==='illustration'?'Illustration':'Location photo'}</span></small></td><td>${s.ports}</td><td><div class="station-row-actions"><button class="table-button" data-assign="${s.id}" ${demo.portfolio.includes(s.id)?'disabled':''}>${demo.portfolio.includes(s.id)?'Assigned':'Assign'}</button><button class="table-button" data-edit-photo="${s.id}">Photo</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No matching stations.</div>'};
actions['client-plan']=()=>{if($('#modal').open)$('#modal').close();adminTab='plan';setRole('admin')};
actions['manage-tariffs']=()=>{adminTab='tariffs';renderAdmin()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.managerView){adminTab=b.dataset.managerView;renderAdmin();if(b.dataset.focusInbox)$('#admin-view .ticket-row')?.scrollIntoView({behavior:'smooth',block:'center'})}if(b.dataset.editPhoto)showPhotoEditor(b.dataset.editPhoto);if(b.dataset.removePhoto){delete demo.stationPhotos?.[b.dataset.removePhoto];activity('Manager removed custom photo for AFDC '+b.dataset.removePhoto);persist();if(selected)updateStationPhoto(selected);$('#modal').close();renderAdmin()}});
document.addEventListener('change',e=>{if(e.target.id==='manager-tier'){chosenTier=e.target.value;normalizeSelection(demo.tariffs.find(t=>t.id===chosenTier));$('#picker-results').innerHTML=pickerRows(demo.tariffs.find(t=>t.id===chosenTier));$('#selection-count').textContent=chosenStations.length+' / '+demo.tariffs.find(t=>t.id===chosenTier).count+' selected';updateTariffMath()}});
document.addEventListener('submit',e=>{if(e.target.id!=='station-photo-form')return;e.preventDefault();const id=Number(e.target.dataset.stationId),s=stations.find(s=>s.id===id);if(!s)return;const path=$('#photo-url').value.trim(),source=$('#photo-source').value.trim(),credit=$('#photo-credit').value.trim();try{if(new URL(path).protocol!=='https:'||new URL(source).protocol!=='https:')throw Error()}catch{$('#photo-error').textContent='Use complete HTTPS links for the image and source.';return}if(!credit){$('#photo-error').textContent='Add a photo credit.';return}const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Checking photo…';const probe=new Image();let completed=false;const finish=ok=>{if(completed)return;completed=true;clearTimeout(timer);if(!ok){submit.disabled=false;submit.textContent='Save location photo';$('#photo-error').textContent='The image could not load. Check the direct image URL.';return}demo.stationPhotos??={};demo.stationPhotos[id]={path,source,credit,alt:`${s.name}, ${s.address}, ${s.city}`,location:`${s.address}, ${s.city}, ${s.state}`};activity('Manager updated location photo for AFDC '+id);persist();if(selected)updateStationPhoto(selected);$('#modal').close();renderAdmin();toast('Location photo saved for this station.')};const timer=setTimeout(()=>finish(false),12000);probe.onload=()=>finish(true);probe.onerror=()=>finish(false);probe.src=path});

// Compact, consistent navigation labels leave readable tap targets on phones.
renderNav=function(){const navs=role==='admin'?[['overview','grid','Overview'],['clients','users','Clients'],['stations','map','Stations'],['requests','chat','Requests'],['tariffs','zap','Plans']]:[['dashboard','grid','Overview'],['map','map','Map'],['assets','assets','My assets'],['documents','file','Documents'],['tariffs','zap','Plans']];$('.main-nav').innerHTML=navs.map(([id,i,label])=>`<button class="nav-item ${(role==='admin'?(adminTab==='plan'?'clients':adminTab):tab)===id?'active':''}" data-tab="${id}">${icon(i)}<span>${label}</span></button>`).join('')};
// Update static titles without adding new dashboard sections.
for(const [selector,title] of [['.filter-panel h2','Station filters'],['.status-panel h2','Directory status'],['.map-heading h2','Explore the charging network'],['.documents-card>h2','Documents'],['.support-card>h2','Your account manager']]){$(selector).textContent=title}
$('.station-card>h2').childNodes[1].textContent=' Selected station ';
$('.document-box [data-action="contract"]').innerHTML=icon('download')+' Download sample';
$('.document-box [data-action="factsheet"]').innerHTML=icon('download')+' Download fact sheet';
// An active plan owns its station selection; directory shortcuts must not desync it.
const unplannedAssignments=assignmentPanel;
assignmentPanel=function(){if(!demo.plan)return unplannedAssignments();return `<section class="panel admin-section"><div class="section-heading"><h2>Plan stations</h2><span>${demo.plan.stationIds.length} selected</span></div>${demo.plan.stationIds.map(id=>stations.find(s=>s.id===id)).filter(Boolean).map(s=>`<div class="activity-row"><strong>${escapeHtml(s.city)}, ${s.state}</strong><small>${escapeHtml(s.name)} · AFDC ${s.id}</small></div>`).join('')}<button class="button secondary" data-manager-view="plan">Edit plan stations</button></section>`};
const assignWithoutPlan=assignStation;
assignStation=function(id){if(demo.plan){adminTab='plan';renderAdmin();toast('Change stations within the active plan, then apply it.');return}assignWithoutPlan(id)};
const adminBeforeScopedForms=renderAdmin;
let managerDirectoryQuery='';
renderAdmin=function(){const search=$('#admin-station-search');if(search)managerDirectoryQuery=search.value;if($('#tariffs-section'))$('#tariffs-section').innerHTML='';adminBeforeScopedForms();if(adminTab==='stations'&&managerDirectoryQuery){$('#admin-station-search').value=managerDirectoryQuery;const query=managerDirectoryQuery.toLowerCase().trim();$('#admin-station-results').innerHTML=directoryRows(stations.filter(s=>`${s.name} ${s.city} ${s.state} ${s.id}`.toLowerCase().includes(query)).slice(0,30))}};
if(selected)updateStationPhoto(selected);
